let hi = scores[0];
for (let i = 1; i < scores.length; i++) {
  if (scores[i] < lo) lo = scores[i];
  if (scores[i] > hi) hi = scores[i];
}
lo = lo - 1;

// TODO: halve the bracket until it is narrower than 1, keeping the half
